import{_ as a,o,c as l,ag as r}from"./chunks/framework.QfQ7DfGu.js";const f=JSON.parse('{"title":"龙架构相关论坛","description":"","frontmatter":{"title":"龙架构相关论坛","outline":"deep"},"headers":[],"relativePath":"misc/loong64-form.md","filePath":"misc/loong64-form.md"}'),t={name:"misc/loong64-form.md"};function n(i,e,p,s,h,c){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="龙芯开源社区" tabindex="-1">龙芯开源社区 <a class="header-anchor" href="#龙芯开源社区" aria-label="Permalink to &quot;龙芯开源社区&quot;">​</a></h1><p>龙芯开源社区是龙芯处理器的基础软件生态建设平台，包含有：</p><ul><li>Loongnix系统安装镜像、虚拟机镜像等下载。</li><li>龙芯浏览器。</li><li>提供 LoongArch 架构下最新 JDK。</li><li>提供 LoongArch 架构下最新 .net。</li><li>提供 LoongArch 架构下的 FFmpeg 与 X264。</li><li>Electron 框架支持。</li><li>以及其他基础软件、图形视频驱动、调试工具、应用工具等。</li></ul><p>社区网址链接：<a href="https://www.loongnix.cn/zh/" target="_blank" rel="noreferrer">https://www.loongnix.cn/zh/</a></p><h1 id="龙芯爱好者社区" tabindex="-1">龙芯爱好者社区 <a class="header-anchor" href="#龙芯爱好者社区" aria-label="Permalink to &quot;龙芯爱好者社区&quot;">​</a></h1><p>龙芯爱好者社区是一个由第三方爱好者、行业人员与学生组成的，致力于龙芯（龙架构）软硬件生态建设的互联网社区。</p><p>其包含的内容有：</p><ul><li>新手资源。包含有踩坑指南、开发指南等入门教程。</li><li>数据材料。包含有芯片规格、产品规格、软硬件兼容数据等信息。</li><li>社区资源。包含有交流论坛、技术分享等内容。</li></ul><p>社区网址链接：<a href="https://loongfans.cn/" target="_blank" rel="noreferrer">https://loongfans.cn/</a></p><h1 id="龙芯应用合作社" tabindex="-1">龙芯应用合作社 <a class="header-anchor" href="#龙芯应用合作社" aria-label="Permalink to &quot;龙芯应用合作社&quot;">​</a></h1><p>龙芯应用合作社，提供龙架构下适配的系统软件，方便下载、安装和使用。</p><p>网址链接：<a href="https://app.loongapps.cn/home" target="_blank" rel="noreferrer">https://app.loongapps.cn/home</a></p>',12)])])}const m=a(t,[["render",n]]);export{f as __pageData,m as default};
